INSERT INTO ep_updates (id,programme_id,period,status,progress,comment,detail,user_id,created_at) VALUES
(1,1,'T1 2026','done',100,'',NULL,NULL,'2026-11-15 17:50:21'),
(2,2,'T1 2026','in_progress',91,'Rapport mensuel élaboré et plans d''actions proposés pour pallier les non-conformités relevées (janvier-février OK, mars en cours). Travaux en cours avec la Finance, DAR, SND (Devices) et Marketing.',NULL,NULL,'2026-11-15 17:50:21'),
(3,3,'T1 2026','delayed',96,'Cartographie des risques élaborée et validée par les responsables d''activités. Plan de contrôle proposé et validé par les responsables d''activités Opérations et les Sup Stores. Hausse des flux de requêtes avec impact négatif sur la réalisation des contrôles planifiés (42/51).',NULL,NULL,'2026-11-15 17:50:21'),
(4,4,'T1 2026','done',100,'',NULL,NULL,'2026-11-15 17:50:21'),
(5,5,'T1 2026','in_progress',50,'En attente de l''implémentation de l''outil de supervision par la DSI.',NULL,NULL,'2026-11-15 17:50:21'),
(6,6,'T1 2026','in_progress',90,'Formation sur Axian Service Now (outil de ticketing) effectuée ; implémentation en cours par la DSI.',NULL,NULL,'2026-11-15 17:50:21'),
(7,7,'T1 2026','in_progress',90,'Création de procédures de résolution de pannes Windows, Hermes, CRM 6D, etc. : en cours d''évaluation.',NULL,NULL,'2026-11-15 17:50:21'),
(8,8,'T1 2026','done',100,'Formations et évaluations effectuées.',NULL,NULL,'2026-11-15 17:50:21'),
(9,9,'T1 2026','in_progress',80,'Base de connaissances Zendesk : KB Chatbot, articles finalisés, intégration en cours ; KB agent interne OK, mise en production imminente. LMS : création des apprenants et des cohortes des stores et du call center.',NULL,NULL,'2026-11-15 17:50:21'),
(10,10,'T1 2026','done',100,'Mise en place de la grille d''évaluation qualité des stores (déploiement T2). Étude de faisabilité d''évaluation KYC archivage effectuée.',NULL,NULL,'2026-11-15 17:50:21'),
(11,11,'T1 2026','in_progress',90,'Retard de réception du planning sur certaines activités, avec reconfiguration des 36 h en 40 h. Mise en œuvre prévue au T2.',NULL,NULL,'2026-11-15 17:50:21'),
(12,12,'T1 2026','done',100,'Recensement exhaustif des outils et plateformes CXO ; formulaire et collecte du feedback des utilisateurs achevés. Analyse des éléments collectés. Prochaine étape : exécution du plan d''amélioration.',NULL,NULL,'2026-11-15 17:50:21'),
(13,13,'T1 2026','in_progress',90,'Nouveau flow IVR défini pour Mobile et fixe. Prochaine étape : validation + implémentation au T2.',NULL,NULL,'2026-11-15 17:50:21'),
(14,14,'T1 2026','in_progress',90,'Présentation du nouveau flow IVR défini pour Mixx ; présentation à Mixx. Prochaine étape : mise en œuvre au T2.',NULL,NULL,'2026-11-15 17:50:21'),
(15,15,'T1 2026','done',100,'Document de cadrage finalisé. Fonctionnalités de l''outil présentées aux parties prenantes (opérations Mixx, partenaires, mobile, fixe, digital, Mixx/juridique, IT). Projet validé + rétroplanning. Prochaine étape : mise en œuvre au T2.',NULL,NULL,'2026-11-15 17:50:21'),
(16,16,'T1 2026','in_progress',100,'Use cases Payement & Network testés. MoU élaboré, validé et signé. Démarrage du POC : configuration OK, enquêtes effectuées.',NULL,NULL,'2026-11-15 17:50:21'),
(17,17,'T1 2026','in_progress',95,'Kickoff réalisé. Rédaction d''articles de la base de connaissance. Gouvernance démarrée.',NULL,NULL,'2026-11-15 17:50:21'),
(18,18,'T1 2026','done',100,'Projet zéro papier en store retenu (notes de service, bons de livraison, etc.). Projet de dashboard facilitant le contrôle des activités d''encaissement en store. Prochaine étape : cadrage du projet au T2.',NULL,NULL,'2026-11-15 17:50:21'),
(19,19,'T1 2026','done',100,'Finalisation des corrections par la DSI. Refresh des équipes. Phase pilote achevée. Prochaine étape : suivi avec objectifs.',NULL,NULL,'2026-11-15 17:50:21'),
(20,20,'T1 2026','in_progress',100,'Projet conditionné par la finalisation du projet Customer segmentation & priorities, achevé en février 2026 au lieu de décembre 2025 prévu au rétroplanning. Prochaine étape : cadrage avec IT & BI sur les intégrations à faire.',NULL,NULL,'2026-11-15 17:50:21'),
(21,21,'T1 2026','in_progress',60,'Quick wins finalisés, en attente de validation IC. Prochaine étape : développement par 6D après validation IC.',NULL,NULL,'2026-11-15 17:50:21');
