INSERT INTO perf_competencies (id,name,description,active,sort_order) VALUES
(1,'Orientation client','Écoute le client, cherche la solution et assure le suivi.',1,10),
(2,'Communication','S''exprime clairement, écoute, adapte son message.',1,20),
(3,'Collaboration','Coopère, partage l''information, aide ses collègues.',1,30),
(4,'Fiabilité et rigueur','Respecte les procédures, les délais et la qualité attendue.',1,40),
(5,'Initiative et autonomie','Propose, prend en charge, avance sans attendre.',1,50),
(6,'Adaptabilité','S''ajuste aux changements et apprend rapidement.',1,60),
(7,'Gestion du stress','Garde sa maîtrise dans les situations tendues.',1,70),
(8,'Esprit d''équipe et leadership','Fédère, donne l''exemple, soutient les autres.',1,80);
