INSERT INTO el_questions (node_id,id,course_id,position,kind,scoring,text,explanation) VALUES
(NULL,1,1,1,'single','strict','Quelle est la première étape d''un échange avec un client ?','On accueille d''abord, puis on écoute le besoin.'),
