INSERT INTO kb_sop_steps (id,sop_id,position,title,instruction,expected,warning,tool,role,duration_min,article_id) VALUES
(1,1,1,'Accueillir et écouter','Laisser le client s''exprimer sans l''interrompre.
INSERT INTO kb_sop_versions (id,sop_id,version,data,user_id,user_name,note,created_at) VALUES
(1,1,1,'{"f":{"title":"Traiter une réclamation client","summary":"Procédure en six étapes, de l''accueil à la clôture.","category_id":1,"objective":"Garantir un traitement homogène et conforme.","scope":"Tous les conseillers clients.","prerequisites":"Accès au CRM et à la téléphonie.","tools":"CRM, téléphonie","tags":"procédure, client","owner_id":1,"estimated_min":null,"risk_level":"critical","mandatory":1,"team_id":null,"internal":0},"steps":[{"position":1,"title":"Accueillir et écouter","instruction":"Laisser le client s''exprimer sans l''interrompre.\\n- Noter les faits\\n- Reformuler le motif","expected":"Le client se sent entendu","warning":null,"tool":null,"role":"Conseiller","duration_min":3,"article_id":null},{"position":2,"title":"Identifier le client et le dossier","instruction":"Rechercher le dossier dans le CRM avec deux informations d''identification.","expected":null,"warning":"Ne jamais communiquer d''information avant l''identification.","tool":"CRM","role":"Conseiller","duration_min":2,"article_id":null},{"position":3,"title":"Qualifier la réclamation","instruction":"Choisir le motif et la gravité dans le formulaire.","expected":null,"warning":null,"tool":"CRM","role":null,"duration_min":2,"article_id":null},{"position":4,"title":"Proposer une solution","instruction":"Appliquer le barème de gestes commerciaux ou escalader vers le niveau 2.","expected":"Solution acceptée ou escalade tracée","warning":null,"tool":null,"role":null,"duration_min":5,"article_id":null},{"position":5,"title":"Confirmer et clôturer","instruction":"Reformuler l''engagement, donner le délai, poser le code de fin d''appel.","expected":null,"warning":null,"tool":"CRM","role":null,"duration_min":2,"article_id":null}]}',NULL,'','Création','2026-11-15 17:50:21'),
(2,2,1,'{"f":{"title":"Clôturer un appel dans le CRM","summary":"Codification, compte rendu et temps de traitement après appel.","category_id":1,"objective":"Garantir un traitement homogène et conforme.","scope":"Tous les conseillers clients.","prerequisites":"Accès au CRM et à la téléphonie.","tools":"CRM, téléphonie","tags":"procédure, client","owner_id":1,"estimated_min":null,"risk_level":"normal","mandatory":0,"team_id":null,"internal":0},"steps":[{"position":1,"title":"Choisir le code de fin d''appel","instruction":"Sélectionner le code qui reflète le résultat réel.","expected":null,"warning":null,"tool":"CRM","role":null,"duration_min":1,"article_id":null},{"position":2,"title":"Rédiger le compte rendu","instruction":"Trois lignes : motif, action, suite.","expected":null,"warning":null,"tool":null,"role":null,"duration_min":2,"article_id":null}]}',NULL,'','Création','2026-11-15 17:50:21'),
(3,3,1,'{"f":{"title":"Escalade vers le niveau 2","summary":"Brouillon à compléter.","category_id":1,"objective":"Garantir un traitement homogène et conforme.","scope":"Tous les conseillers clients.","prerequisites":"Accès au CRM et à la téléphonie.","tools":"CRM, téléphonie","tags":"procédure, client","owner_id":1,"estimated_min":null,"risk_level":"normal","mandatory":0,"team_id":null,"internal":0},"steps":[{"position":1,"title":"Qualifier le besoin d''escalade","instruction":"À rédiger.","expected":null,"warning":null,"tool":null,"role":null,"duration_min":null,"article_id":null}]}',NULL,'','Création','2026-11-15 17:50:21');
