INSERT INTO cs_script_versions (id,script_id,version,data,user_id,user_name,note,created_at) VALUES
(1,1,1,'{"f":{"title":"Accueil client — appel entrant","kind":"accueil","channel_id":1,"language":"fr","situation":"Premier contact avec le client.","body":"Bonjour, vous êtes en relation avec {{prenom_conseiller}}, merci d''appeler. Puis-je connaître votre nom ?\\nMerci {{nom_client}}, je vous écoute.","avoid":"« Ce n''est pas mon problème »\\n« Vous auriez dû… »","required_phrases":"Formule de salutation et prénom du conseiller","team_id":null,"mandatory":1,"owner_id":1,"family":null,"keywords":null},"points":[{"position":1,"label":"Salutation et présentation du conseiller","mandatory":1,"weight":2},{"position":2,"label":"Demande du nom du client","mandatory":0,"weight":1},{"position":3,"label":"Ton chaleureux et rythme adapté","mandatory":0,"weight":1}]}',NULL,'','Création','2026-11-15 17:50:21'),
(2,2,1,'{"f":{"title":"Clôture d''appel","kind":"cloture","channel_id":1,"language":"fr","situation":"Fin de l''échange avant de raccrocher.","body":"Pour résumer, {{resume}}. Y a-t-il autre chose que je puisse faire pour vous ?\\nMerci {{nom_client}} de votre appel, excellente journée.","avoid":"« Ce n''est pas mon problème »\\n« Vous auriez dû… »","required_phrases":"Formule de salutation et prénom du conseiller","team_id":null,"mandatory":0,"owner_id":1,"family":null,"keywords":null},"points":[{"position":1,"label":"Reformulation de la solution","mandatory":1,"weight":2},{"position":2,"label":"Proposition d''aide complémentaire","mandatory":1,"weight":1},{"position":3,"label":"Remerciement et formule de politesse","mandatory":0,"weight":1},{"position":4,"label":"Information sur l''enquête de satisfaction","mandatory":0,"weight":1}]}',NULL,'','Création','2026-11-15 17:50:21'),
(3,3,1,'{"f":{"title":"Traitement d''une objection tarifaire","kind":"objection","channel_id":1,"language":"fr","situation":"Le client juge l''offre trop chère.","body":"Je comprends votre remarque, {{nom_client}}. Comparons ce que vous obtenez réellement…","avoid":"« Ce n''est pas mon problème »\\n« Vous auriez dû… »","required_phrases":"Formule de salutation et prénom du conseiller","team_id":null,"mandatory":0,"owner_id":1,"family":null,"keywords":null},"points":[{"position":1,"label":"Reconnaître l''objection","mandatory":1,"weight":1}]}',NULL,'','Création','2026-11-15 17:50:21'),
(4,4,1,'{"f":{"title":"Demande de remboursement FTTH (annulation de souscription fibre)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋 \\nJ’ai bien reçu votre demande d’annulation de souscription à la Fibre Yas et je vais vous accompagner dans les démarches.\\nPour traiter votre demande, pourriez-vous s’il vous plaît me transmettre les éléments suivants :\\n1️⃣ Les photos recto et verso de votre pièce d’identité en cours de validité (Carte nationale d’identité, Passeport, Carte consulaire,  Carte de séjour,  Carte des forces armées togolaises, Permis de conduire, Carte d''électeur établie à partir de 2023) ;\\n2️⃣ Le numéro de ligne attribué à votre demande (si disponible) ;\\n3️⃣ La capture d’écran du message de confirmation du paiement des frais d’installation via Mixx by Yas  (si disponible) ;\\n4️⃣ Le motif de votre demande d’annulation ;\\n5️⃣ Le numéro sur lequel vous souhaitez recevoir le remboursement après traitement. S''assurer du numéro qui a effectué le paiement de la souscription pour le remboursement FTTH  car le délai est 3 jours sinon 7 jours.\\nDès réception de ces informations, votre demande sera analysé et un retour vous sera fait dans les meilleurs délais (SLA  3 jours  ( mode de paiement Mixx) ou 7 jours ( mode de paiement Sage X3 en store) ouvrés à partir du jour d''envoi du dossier en fonction du mode de paiement.\\nJe reste à votre disposition pour toute assistance complémentaire.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"remboursement rembourser annulation fibre ftth internet domicile box modem wifi"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(5,5,1,'{"f":{"title":"NET_illimité_7J: 15Go + Connexion non-stop (7j) 3 999 F","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBonne nouvelle !\\nVotre forfait Illimité Hebdo est actif et vous permet de profiter de vos services pendant 7 jours\\n🚀 Pour une meilleure expérience, privilégiez un usage raisonnable du partage de connexion et continuez à profiter pleinement de votre forfait tout au long de sa période de validité.\\n💡 Petit conseil pour en profiter au maximum : ce forfait est conçu pour un usage personnel et équilibré. En cas d’utilisation très intensive du partage de connexion (hotspot), notamment au-delà des 15 Go inclus, la qualité de service peut être impactée.\\nUne question sur votre forfait ou sur votre consommation ? \\nJe reste à votre disposition pour vous accompagner 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(6,6,1,'{"f":{"title":"Forfait 1 499 F – 5 Go \\/ 3 jours : la data finit vite","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nAvec votre forfait à 1 499 F, profitez de 5 Go d’internet valables pendant 3 jours\\n🚀 Pour profiter plus longtemps de votre forfait, pensez à privilégier le Wi-Fi pour les usages les plus gourmands en données lorsque cela est possible.\\n💡 À savoir : La vitesse à laquelle les 5 Go sont consommés dépend de vos usages. Les vidéos en streaming, les téléchargements ou encore le partage de connexion peuvent utiliser davantage de données.\\n📲 Pour suivre votre consommation à tout moment, composez *909*0#.\\nPrêt à activer votre prochain forfait internet ? \\nJe suis là pour vous accompagner 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"data finit vite consommation internet forfait épuisé"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(7,7,1,'{"f":{"title":"Avantages de la Yas App","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n📱 Votre ligne dans votre poche, 24h\\/24 : c’est ça, Yas App !\\n💡 Fini les multiples codes à retenir ! \\nAvec la Yas App, tout est regroupé au même endroit pour vous simplifier la vie et vous faire gagner du temps.\\n Vous pouvez :\\n✅ Consulter votre solde en temps réel (crédit, internet, SMS) et suivre votre consommation\\n✅ Consultez votre solde et suivez votre consommation en temps réel\\n✅ Achetez vos forfaits internet, voix, et mixte en toute simplicité\\n✅ Rechargez votre numéro ou celui de vos proches\\n✅ Retrouvez l''historique de vos transactions à tout moment\\n✅ Profitez de bonus, récompenses, offres exclusives et programmes de parrainage\\n✅ Accédez rapidement à certains services et à l''assistance lorsque vous en avez besoin\\n📥 Téléchargez-la gratuitement :\\n• Sur Play Store (Android)\\n• Sur App Store (iPhone)\\n💛 Dites-moi dès que l’application est installée, et je serai ravi de vous accompagner pour vos premiers pas avec Yas App","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"yas app application mobile"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(8,8,1,'{"f":{"title":"Forfait lékèdè – Récupérer un forfait expiré (conditions)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBonne nouvelle !  Le reliquat d’un forfait expiré peut être récupéré\\n ✅ Voici comment :\\n📅 Si votre forfait est valable pour 10 jours ou moins, il suffit de recharger le même forfait dans les 10 jours suivant son expiration.\\n📅 Si votre forfait est valable plus de 10 jours → vous disposez de 30 jours après son expiration pour recharger le même forfait.\\nSi ces conditions sont remplies, votre reliquat est récupéré.\\nBesoin d’être guider pour recharger votre compte ? Je suis là 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"numéro supprimé inactif réattribué récupérer reprise forfait expiré lékèdè lema volume"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(9,9,1,'{"f":{"title":"Forfaits non cumulables en validité – explication + récupération du volume","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n😊 Je comprends votre étonnement, je vous explique tout de suite.\\nLes durées de validité des forfaits ne s''ajoutent plus. Seule la validité du dernier forfait activé est prise en compte.\\n🔎 Après vérification, votre dernière souscription a été effectuée le {{date}} à {{heure}} pour une durée de [nombre ] jours. Votre forfait est donc valable jusqu’au {{date}} à {{heure}}.\\nBonne nouvelle ! : Votre volume restant peut être récupéré !\\n📅 Si votre forfait est valable pour 10 jours ou moins, il suffit de reprendre le même forfait dans les 10 jours suivant son expiration.\\n📅 Si votre forfait est valable plus de 10 jours, vous disposez de 30 jours après son expiration pour reprendre le même forfait \\nSi ces conditions sont remplies, vous récupérez votre volume restant.\\n😊 Je reste disponible si vous avez besoin d''autres informations.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"numéro supprimé inactif réattribué récupérer reprise"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(10,10,1,'{"f":{"title":"Retrouver son code de parrainage","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🔥 Votre code de parrainage est à portée de clic !\\/Prêt à parrainer ? Ton code t''attend dans Yas App !\\n✅ Ouvrez Yas App\\n ✅ Aller dans « Parrainer et gagner »\\n ✅ Faites défiler vers le bas\\n ✅ Cliquez sur « Invitez et gagnez dès maintenant »\\n🎉Votre code s''affiche automatiquement !\\n🚀 Envoyez-le à vos proches et commencez à gagner des récompenses.\\n💛 N''attendez plus, testez-le maintenant !\\n✨ À vous de jouer !","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"parrainage code parrain filleul gain"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(11,11,1,'{"f":{"title":"Quiz Yas App – gain non attribué (réponse négative)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🙏 Merci d’avoir participé au quiz.\\nAprès vérification, les récompenses sont attribuées automatiquement en fonction des réponses enregistrées. \\nJe ne peux pas modifier le résultat obtenu.\\nBonne nouvelle ! Vous avez d’autres possibilités de gagner des bonus directement sur Yas App.\\n🤝 Parrainez vos proches et gagnez ensemble : \\n1️⃣ Ouvrez Yas App\\n 2️⃣ Rendez-vous dans « Parrainer et gagner »\\n 3️⃣ Partagez votre code de parrainage avec vos proches\\n 4️⃣ Dès qu’ils l’utilisent, vous recevez tous les deux une récompense\\n🚀 Plus vous invitez de personnes, plus vous multipliez vos chances de gagner des avantages.\\nBesoin d’une assistance pour retrouver votre code de parrainage ? \\nJe peux vous guider étape par étape 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"jeu quiz concours gain cadeau récompense yas app application mobile"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(12,12,1,'{"f":{"title":"Requête du client peu claire – Comment demander une précision au client","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nMerci de nous avoir contactés.\\nPour mieux vous accompagner, pouvez-vous nous indiquer l''objet de votre demande (forfait, solde, Mixx By Yas, Fibre Yas ou autre service) ?\\n🎉 Je vous apporte la réponse adaptée dès réception de votre précision.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"précision flou clarifier incompréhensible détails"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(13,13,1,'{"f":{"title":"Parrainage – Comment récupérer mon gain","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nPour recevoir votre bonus de parrainage, votre filleul doit renseigner votre code après l''installation de Yas App.\\nVoici la marche à suivre :\\n1️⃣ Ouvrez Yas App\\n 2️⃣ Sélectionnez « Parrainer et gagner »\\n3️⃣ Cliquez sur « Récupérer mon gain »\\n4️⃣  Saisissez votre code de parrainage\\n5️⃣ Cliquez sur « Obtenir ma récompense »\\n🎉Le bonus est alors crédité automatiquement au parrain et au filleul.\\nBonne expérience avec Yas App !","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"parrainage code parrain filleul gain numéro supprimé inactif réattribué récupérer reprise"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(14,14,1,'{"f":{"title":"Forfaits cumulés en volume mais pas en validité (ex. Lema 1000 FCFA)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nJe comprends votre situation et je vais vous apporter quelques précisions.\\nLes forfaits se cumulent en volume, mais pas en validité. \\nLorsqu''un nouveau forfait est activé, la durée de validité démarre immédiatement à la date et à l''heure d''activation du nouveau forfait, même si le précédent n''est pas encore expiré.\\nVotre volume a donc bien été cumulé et la validité appliquée conformément aux conditions du forfait.\\nAinsi, dans le cas d''un forfait Lema 1 000 FCFA souscrit avant l''expiration du précédent, le volume est bien ajouté à votre solde, mais la nouvelle validité s''applique à partir de la date et de l''heure de la dernière souscription.\\nJe suis là si vous avez d’autres questions 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"forfait expiré lékèdè lema récupérer volume"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(15,15,1,'{"f":{"title":"SIM supprimée pour une durée d’inactivité de six ( 6) mois","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nJe comprends votre déception et je vais vous expliquer la situation.\\n📌 Lorsque votre numéro n''a pas été rechargé pendant  6 mois,  il peut recevoir mais ne peut plus émettre d''appels. Dans ce cas, une simple recharge permet généralement sa réactivation.\\n📌 Lorsque votre numéro n''a pas été rechargé pendant plus de 9 mois, il est supprimé et ne pourra plus être récupéré.\\n📩 Concernant les notifications, un SMS d''information est généralement envoyé. Toutefois, celui-ci ne peut être reçu que si la carte SIM est insérée dans un téléphone allumé et connecté au réseau.\\n💡 Pour éviter cette situation à l''avenir, il suffit d''effectuer une recharge de temps en temps afin de maintenir la ligne active.\\nN’hésitez pas à me solliciter, je serai ravi de vous accompagner","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"carte sim puce numéro supprimé inactif réattribué récupérer reprise"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(16,16,1,'{"f":{"title":"Fibre Yas – forfait expiré, invitation à renouveler","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nVotre abonnement Fibre Yas est arrivé à expiration le {{date}} à {{heure}}.\\n⚡ Ne manquez rien de vos activités en ligne ! Renouvelez votre forfait et profitez à nouveau d''une connexion performante et illimitée.\\n✅ Renouvellement : *909*101#\\n ✅ Vérification de l''abonnement : *909*106#\\n📌 Réactivez votre forfait en quelques instants et restez connecté(e).\\nMerci d''avoir choisi Yas 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"fibre ftth internet domicile box modem wifi forfait expiré lékèdè lema récupérer volume"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(17,17,1,'{"f":{"title":"PI-SPI – explication du service","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nConnaissez-vous le PI-SPI (Plateforme Interopérable du Système de Paiement Instantané) ? \\n ✨ Avec le PI-SPI, transférer et recevoir de l''argent devient plus simple, plus rapide et plus sécurisé, quel que soit votre opérateur ou votre banque. \\nCette initiative de la BCEAO vous permet de bénéficier de :\\n ✅ Une couverture régionale dans les 8 pays de l''UEMOA\\n✅ Des transferts instantanés 24h\\/24 et 7j\\/7\\n ✅ Une interopérabilité totale : envoyez ou recevez de l''argent entre banques, mobile money et institutions de microfinance, même si vous n''utilisez pas le même opérateur\\n ✅ Des transferts gratuits entre particuliers\\n ✅ Une sécurité renforcée grâce à la validation en temps réel des transactions\\nMerci de faire confiance à Mixx Togo💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"pispi bceao uemoa instantané"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(18,18,1,'{"f":{"title":"Envoi d’un relevé de transactions par e-mail","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n📎 Votre relevé des transactions pour le numéro [XX XX XX XX] est disponible en pièce jointe.\\n🔎 Besoin d''un relevé sur une autre période ou d''informations complémentaires ? \\nN''hésitez pas à me le faire savoir, je m''en occupe avec plaisir.\\n✨ Je suis là et je vous souhaite une excellente journée. 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"relevé historique transactions détail email mail courriel"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(19,19,1,'{"f":{"title":"Jeu Quiz retiré – autres moyens de gagner","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nLe jeu Quiz n’est plus disponible sur la nouvelle version de Yas App, mais il reste de belles façons de gagner des récompenses :\\n🤝 Parrainage : invitez vos proches à installer l’application. Une fois installée, ils saisissent votre code de parrainage, et vous gagnez des bonus tous les deux 🎁\\n🎮 Tentez votre chance avec Win Pizz .\\nParticipez régulièrement aux jeux disponibles et multipliez vos opportunités de remporter des cadeaux et récompenses 🎊\\n💛 Merci pour votre fidélité et votre confiance. Restez connecté, de nouvelles surprises vous attendent sur Yas App !\\nÀ très bientôt","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"jeu quiz concours gain cadeau récompense"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(20,20,1,'{"f":{"title":"Gagner des récompenses (data) sur Yas App","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nEnvie de gagner de la data sur Yas App ? \\n🤝Parrainez vos proches avec votre code de parrainage et profitez de bonus ensemble \\n🎮 Jouez chaque jour au Win Pizz pour tenter de remporter encore plus de récompenses.\\n✨ Prêt à relever le défi ? À vous de jouer ! 🚀","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"yas app application mobile"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(21,21,1,'{"f":{"title":"Mise en attente – accusé de réception d’un e-mail","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nMerci pour votre message 💛\\nJe l’ai bien reçu et je m’occupe de votre demande.\\nJe reviens vers vous dans les meilleurs délais avec toutes les informations nécessaires.\\nMerci de votre patience, et à très vite 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"attente patienter instant un moment email mail courriel"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(22,22,1,'{"f":{"title":"Requête du client peu claire – Comment demander une précision au client","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n👋 Je suis là pour vous assister !\\nPour que je puisse vous accompagner au mieux, pouvez-vous me donner un peu plus de détails sur votre demande ? \\n [Le Conseiller Clientèle recueille les précisions nécessaires auprès du client pour traiter efficacement sa requête] 😊\\n📌 Plus votre description est précise, plus je pourrai vous apporter une réponse rapide et adaptée.\\n🎉 Je vous apporte une réponse dès réception de votre précision.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"précision flou clarifier incompréhensible détails"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(23,23,1,'{"f":{"title":"Demande d’aide financière – Clarification sur le service d’assistance Yas","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nLe message reçu provient bien de notre service d’assistance Yas.\\nJe suis là pour vous accompagner sur toutes vos demandes liées à nos offres et services 💛\\nℹ️ Ce canal n''est pas destiné aux demandes d’aide financière.\\nJe reste disponible si vous avez la moindre question ou besoin d''assistance 💛😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(24,24,1,'{"f":{"title":"Suggestion d’amélioration – Auto-annulation des transactions Mixx Togo","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nMerci pour votre suggestion 💡 Elle a bien été partagée avec nos équipes afin d'' améliorer votre expérience avec Mixx Togo.\\nPetit point utile concernant l''auto- annulation des transactions 👇\\n⏰ L''annulation est possible dans un délai de 48 heures après la transaction.\\n🔄 Vous pouvez faire jusqu''à deux demandes d''annulation par jour.\\n✅ Jusqu''à 20 000 F CFA, l''annulation de la transaction est automatique et le remboursement est immédiat.\\n✅ Au-delà de 20 000 F CFA, le montant est débité du compte du bénéficiaire mais n’est pas automatiquement remis sur le compte de l’initiateur. Une vérification est nécessaire. Nos équipes contactent alors le bénéficiaire afin d''analyser les circonstances de la transaction avant toute éventuelle restitution des fonds.\\n💬 Besoin d''un accompagnement sur votre situation ? Écrivez-moi en message privé :\\n👉 Facebook Messenger https:\\/\\/m.me\\/yasintogo\\n 👉 WhatsApp +22890928888\\nJe reste disponible si vous avez la moindre question ou besoin d''assistance 💛😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(25,25,1,'{"f":{"title":"Accueil client – Prise de contact","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBienvenue chez Yas 😊\\nUne question, ou un besoin d’information sur l''un de nos services ? Je suis là pour vous guider.\\n💬 Dites-moi ce que je peux faire pour vous aujourd''hui ! ✨","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"bonjour accueil salutation bienvenue premier contact"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(26,26,1,'{"f":{"title":"Erreur de transfert ( SLA 5 jours ouvrés ) ou de retrait ( SLA 3 à 7 jours ouvrés ) ou de dépôt ( SLA 48h ) Mixx Togo","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nJe comprends votre inquiétude et je m’en occupe 🙏\\nPour me permettre de vérifier votre transaction et vous accompagner au mieux, pourriez-vous m''envoyer s''il vous plaît :\\n📱 Le numéro de téléphone utilisé pour la transaction\\n👤 Vos nom et prénom\\n📸 Une capture d’écran du message de confirmation de la transaction\\nDès réception de ces informations, je transmettrai votre demande pour analyse ✅\\n💡 Un retour vous sera fait dans un délai maximum [ Le conseiller client communique au client le délai de restitution (SLA) en vigueur et s''assure de sa bonne compréhension].\\nMixx Togo vous remercie  pour votre fidélité et votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"transfert envoi argent erreur mauvais numéro annuler"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(27,27,1,'{"f":{"title":"Service Actu Sport – débits de 25 F","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nAprès vérification, j’ai trouvé l’origine des prélèvements.\\nIl s’agit du service Actu Sport, qui prélève 25 F CFA sur votre crédit à chaque renouvellement.\\n📲 Pour arrêter ces prélèvements, il vous suffit de composer : *909*5*3*9#\\n✅ Une fois la désactivation effectuée, les prélèvements s''arrêteront automatiquement.\\nSi vous avez besoin d''assistance, je suis là pour vous accompagner.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"prélèvement débit abonnement désabonnement stop service payant lenteur connexion lente internet coupure"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(28,28,1,'{"f":{"title":"Message de mise en attente","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nMerci pour votre message\\n🙏 Accordez-moi un instant s''il vous plaît, je reviens vers vous dès que j''ai toutes les informations utiles.\\nMerci pour votre patience et votre confiance 🤝","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"attente patienter instant un moment"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(29,29,1,'{"f":{"title":"Demande en cours de traitement","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBonne nouvelle ! J’ai vérifié et votre demande est bien prise en charge.\\n⏳ Elle suit actuellement son parcours de traitement. \\nEncore un peu de patience, nos équipes s’en occupent.\\nJe reste à vos côtés et je ne manquerai pas de vous tenir informé(e).\\n💛 Merci pour votre confiance.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(30,30,1,'{"f":{"title":"Invitation à poursuivre en message privé","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n💬 Besoin d''un accompagnement sur votre situation ? Écrivez-moi en message privé :\\n👉 Facebook Messenger https:\\/\\/m.me\\/yasintogo\\n 👉 WhatsApp  +22890928888\\nJe reste disponible pour vous guider 💛😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"message privé messenger whatsapp inbox"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(31,31,1,'{"f":{"title":"Élargissement de compte Mixx Togo – KYC 2 en store","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nFaites votre demande en agence Yas, et auprès des Express.\\n L’élargissement est gratuit 😊. Votre demande sera traitée dans un délai maximum de 48 h!\\nVoici les pièces requises pour élargir votre compte (au choix) :\\n✅ Carte nationale d’identité\\n✅ Passeport\\n✅ Carte consulaire\\n✅ Carte de séjour\\n✅ Carte des forces armées togolaises\\n✅ Permis de conduire\\nBonne nouvelle ! Téléchargez vite l’application Mixx et élargissez votre compte gratuitement ! 🚀\\nMerci pour votre confiance 🙏🏾","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"kyc élargissement compte élargi pièces identité"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(32,32,1,'{"f":{"title":"Élargissement de compte à distance – Via l''application Mixx Togo","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBonne nouvelle ! Plus besoin de vous déplacer. \\nTéléchargez vite l’application Mixx et élargissez votre compte gratuitement 🚀\\nPréparez simplement l’une des pièces suivantes en cours de validité :\\n✅ Carte nationale d’identité\\n✅ Passeport\\n✅ Carte consulaire\\n✅ Carte de séjour\\n✅ Carte des forces armées togolaises\\n✅ Permis de conduire\\nMerci pour votre confiance 🙏🏾","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"kyc élargissement compte élargi pièces identité"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(33,33,1,'{"f":{"title":"Votre compte Mixx Togo est-il bien à votre nom ?","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBonne nouvelle ! Après vérification, votre numéro de téléphone est bien enregistré à votre nom.\\nMais le compte Mixx n’est pas enregistré en votre nom. Pas d''inquiétude, je m ''occupe de tout pour régulariser la situation !\\nPour cela, envoyez-moi simplement une photo bien lisible du recto et du verso de votre pièce d’identité en cours de validité : \\n✅ Carte nationale d’identité\\n✅ Passeport\\n✅ Carte consulaire\\n✅ Carte de séjour\\n✅ Carte des forces armées togolaises\\n✅ Permis de conduire\\n📸. Petite astuce : posez-la sur un support clair pour une meilleure visibilité !\\nDès réception de vos photos, je traite votre demande immédiatement.\\nMerci pour votre confiance !  Je suis là si vous avez d''autres questions 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(34,34,1,'{"f":{"title":"SIM endommagée ( le CC vérifie au préalable si l''identité du client est conforme dans CRM)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nOups, votre carte SIM fait des siennes ? \\nEssayons d’abord une vérification rapide 🔧 : insérez votre SIM dans un autre téléphone.\\nSi le problème persiste, la SIM est peut-être endommagée. Dans ce cas, rendez-vous dans une agence Yas avec l’une des pièces suivantes en cours de validité : \\n✅ Carte nationale d’identité\\n✅ Passeport\\n✅ Carte consulaire\\n✅ Carte de séjour\\n✅ Carte des forces armées togolaises\\n✅ Permis de conduire\\n✅ Carte d''électeur (établie à partir de 2023)\\n✅ Carte ANID\\nUn conseiller clientèle vous assistera sur place.\\n💡 Prévoyez 500 FCFA si un remplacement de SIM est nécessaire.\\n Merci pour votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"carte sim puce perdue volée cassée endommagée défectueuse"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(35,35,1,'{"f":{"title":"Changement d’identité \\/ SIM perdue ou endommagée – Lettre d’engagement","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nJe comprends votre stress, mais pas de panique : on va récupérer votre numéro ensemble ! 💪\\nLa solution : faire un changement d’identité sur la ligne pour que vous puissiez ensuite retirer votre nouvelle SIM en agence.\\nVoici la marche à suivre 📝 :\\n1️⃣ Écrivez, datez et signez la lettre ci-dessous sur papier.\\n2️⃣ Prenez en photo cette lettre (ou générez un PDF).\\n3️⃣ Envoyez-moi les photos recto\\/verso de votre pièce d’identité originale et en cours de validité.\\n💡 Petite astuce : des photos bien nettes et lumineuses permettent un traitement ultra-rapide ! 📲\\nMerci pour votre patience et votre confiance 💛\\n\\n— — — Modèle de lettre — — —\\nJe soussigné(e) …………………… (Nom et prénom du client) atteste être propriétaire et utilisateur du numéro d’appel …………………… depuis ……………………\\nLes numéros que j’appelle le plus souvent sont les suivants : …………………… et mon dernier rechargement était le ……………………\\nJe m’engage à le céder à toute personne qui se présenterait à vos services avec des preuves plus convaincantes que les miennes.\\nFait à (ville de résidence), le (date)\\nSignature du client\\n— — — — — — — — — — — — — —","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"carte sim puce perdue volée cassée endommagée défectueuse"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(36,36,1,'{"f":{"title":"Lettre d’engagement incomplète","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nNous y sommes presque ! Juste un petit détail : votre lettre est incomplète 🖊️\\nPouvez-vous la recopier en suivant bien le modèle envoyé et remplir les zones vides avant de me la renvoyer ?\\nMerci pour votre collaboration 🙏 \\nJe traite votre demande dès réception.\\nSi vous avez besoin d''une assistance, je suis là 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(37,37,1,'{"f":{"title":"Lettre requise pour traiter la demande","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nPour avancer sur votre demande, j''ai juste besoin de la lettre rédigée en entier selon le modèle envoyé 📝.\\n👉 Une fois rédigée, envoyez-moi une photo bien nette, et je prends le relais immédiatement !\\nMerci pour votre collaboration 🙏  \\n Un doute ou besoin d''assistance ? Je suis juste là 💛.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(38,38,1,'{"f":{"title":"Test d’éligibilité fibre – envoi de la localisation GPS","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nVérifions ensemble si la fibre arrive chez vous ! \\n🚀 J’ai juste besoin de votre position GPS.\\nC''est super simple, voici comment faire sur WhatsApp :\\n1️⃣ Appuyez sur le petit trombone 📎 (ou le bouton +) juste à côté de là où vous écrivez.\\n2️⃣  Sélectionnez « Localisation ».\\n3️⃣ Patientez une seconde pour que votre téléphone se cale bien (visez une précision de ± 3 à 4 mètres).\\n4️⃣ Cliquez sur « Envoyer ma localisation actuelle » et le tour est joué !\\n⚠️ Petite astuce : Assurez-vous d’être à l’endroit exact où vous souhaitez que la fibre soit installée avant d’envoyer. 🏠\\nDès que je reçois votre position, je passe à l''action et je vous donne le résultat ! 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"fibre ftth internet domicile box modem wifi"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(39,39,1,'{"f":{"title":"Fibre – zone non couverte","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nAprès vérification, votre zone n’est pas encore couverte. \\nLe réseau grandit et se déploie jour après jour de façon progressive pour arriver très vite chez vous 📈.\\n💡 Bonne nouvelle, j''ai un plan B ! \\nEn attendant la fibre, on ne vous laisse pas sans connexion. \\nJe peux vous proposer nos super solutions internet à domicile ou à emporter partout avec vous (Box 4G ou MiFi).\\nIntéressé ? Dites-le- moi et je vous explique les détails ! 😉\\nMerci pour votre patience et votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"fibre ftth internet domicile box modem wifi"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(40,40,1,'{"f":{"title":"MiFi et routeurs mobiles – catalogue","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}},\\nBénéficiez d''une connexion haut débit stable et performante, à domicile comme en mobilité. \\nPassez  dans  nos agences Yas Togo, découvrir notre gamme d''équipements au réseau internet disponibles:\\n📦 MIFI Notion M016 - 30 990 FCFA \\nInclus : un équipement MiFi 4G+, un kit de connexion 4G+ et un volume data de 60 Go.\\n• Batterie : 3 000 mAh.\\n• Partage : Hotspot Wi-Fi prenant en charge jusqu’à 10 connexions simultanées.\\n• Usage : Idéal lors de vos déplacements.\\n📱 MiFi Harvilon – 29 900 FCFA\\nBonus : 60 Go de data offerts, valables pendant 30 jours.\\n• Connectivité : Equipement 4G+, ports Ethernet et connectivité Wi-Fi.\\n• Autonomie & Stockage : Batterie intégrée de 2 100 mAh.\\n• Capacité : Compatibilité 4G\\/LTE (Cat 4) prenant en charge jusqu''à 10 connexions simultanées.\\n🖥️ Box 4G Nokia – 39 900 FCFA \\nBonus : 60 Go offerts valables 30 jours.\\n• Couverture : Wi-Fi haute capacité supportant jusqu’à 32 utilisateurs simultanés.\\n• Technologie : Compatibilité 4G\\/LTE avec des débits s''élevant jusqu’à 150 Mbps.\\n• Batterie : 4 000 mAh.\\n🔗 Consultez l''intégralité de nos offres sur notre catalogue en ligne : yas.tg\\/devices\\nJe reste là si vous avez des questions 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"mifi box 4g routeur internet maison"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(41,41,1,'{"f":{"title":"Assistance Roaming – paramétrage","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBonne nouvelle, votre service Roaming est activé ! \\n📶 Voyons tout de suite comment le configurer pour en profiter un maximum sur votre téléphone.\\nVoici vos petites étapes de paramétrage 🔧 :\\n1️⃣ Rendez-vous dans les Paramètres de votre téléphone, puis sélectionnez Réseaux mobiles.\\n2️⃣ Activez la sélection automatique des réseaux. \\nVotre téléphone se connectera tout seul au meilleur opérateur partenaire sur place.\\n❗ Le réseau joue les difficiles ? \\n1️⃣ Désactivez la sélection automatique.\\n2️⃣ Sélectionnez manuellement les réseaux qui s''affichent, un par un.\\n3️⃣ Passez un petit coup de fil de test sur chaque réseau pour trouver celui qui fonctionne !\\n4️⃣ Dès que l''appel passe, vous avez trouvé le bon réseau !\\nLe réseau ne passe toujours pas ! \\nEteignez votre téléphone puis  redémarrez -le !\\n📞 Puis passez un appel : Composez l''indicatif du pays suivi du numéro.\\n Exemple : 22890XXXXXX (si vous appelez vers le Togo).\\n📲 C''est le moment du petit test 😊 : composez l''un de vos codes habituels, comme *145*7*1#\\nFaites-moi un petit retour pour me dire si tout fonctionne, et on avance ensemble ! 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"roaming international étranger voyage"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(42,42,1,'{"f":{"title":"Demande de reprise de numéro Yas","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nVotre numéro semble être inactif ?\\nVous souhaitez le reprendre ? Il  n’est peut-être pas perdu !\\nTentons ensemble de le récupérer 💪\\n💛 Passez en agence avec les documents ci-dessous, nos équipes en agence sont disponibles pour vous assister dans vos démarches : \\n🪪 L''original de votre pièce d’identité en cours de validité (Carte nationale d’identité, Passeport, Carte consulaire,  Carte de séjour,  Carte des forces armées togolaises, Permis de conduire, Carte d''électeur établie à partir de 2023) ;\\n 📄 Un justificatif prouvant que vous étiez l’utilisateur du numéro : un talon d’identification, un reçu d’achat du kit ou  un dernier reçu de changement Sim, une pochette du kit ou une étiquette du numéro\\nN.B : Le client devra une fois sur place rédigée un courrier de demande de reprise de numéro (exemplaire disponible en boutique).\\n1- Au cas où le client a déposé directement son courrier de demande de reprise de numéro au siège de YAS TOGO, le courrier est transféré à l''agence de prise en charge souhaitée.\\n2-  Au cas où une tierce personne est envoyée pour le retrait du numéro, elle devra présenter une procuration légalisée signée de la demande de reprise de numéro et les originaux de la pièce d’identité en cours de validité de l''utilisateur et de la tierce personne. \\n💰 Frais : 2 500 FCFA (uniquement si la récupération est possible)\\nJe reste là si vous avez des questions 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"numéro supprimé inactif réattribué récupérer reprise"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(43,43,1,'{"f":{"title":"Fraude en ligne – transactions non annulables","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n💛 Je comprends votre déception et je m''excuse pour le désagrément causé.\\nD''après les éléments que vous avez partagés, il semble que vous ayez été victime d''une arnaque. Les opérations enregistrées correspondent à des paiements effectués en ligne et ne peuvent donc pas être annulées.\\n💪 Même si cette situation est difficile, elle peut aussi devenir un réflexe de vigilance pour l''avenir : \\n🔹 Vérifiez toujours l''origine des demandes reçues.\\n 🔹 Soyez prudent face aux offres trop attractives.\\n 🔹 Gardez vos codes personnels strictement confidentiels.\\n💛 En partageant cette expérience autour de vous, vous pouvez contribuer à protéger d''autres personnes.\\nJe reste disponible si vous avez d''autres questions. 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"arnaque fraude escroquerie phishing piratage faux lien"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(44,44,1,'{"f":{"title":"Fibre – zone non éligible (après envoi des coordonnées)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🙏 Merci pour votre intérêt pour la fibre Yas et pour les informations partagées.\\nAprès vérification, votre zone n''est pas encore couverte à ce jour. Toutefois, nos équipes poursuivent le déploiement du réseau afin de rendre la fibre accessible au plus grand nombre.\\n💡 En attendant son arrivée, profitez d''alternatives pratiques et performantes comme nos solutions MiFi et Box 4G.\\n🤝 Je vous en parle si vous le souhaitez !\\n Merci pour votre confiance ! 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"fibre ftth internet domicile box modem wifi"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(45,45,1,'{"f":{"title":"Configuration APN –Internet sur iPhone","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🚀 Remettons ensemble votre connexion Internet en service !\\nSuivez simplement ces quelques étapes sur votre iPhone :\\n🔧 Configuration des données mobiles :\\n1️⃣ Ouvrez Réglages\\n 2️⃣ Sélectionnez Données cellulaires\\n 3️⃣ Appuyez sur Options, puis Réseau de données cellulaires\\n 4️⃣ Saisissez les informations suivantes :\\n✅Nom du point d''accès : internetd.togocel\\n✅ Nom d''utilisateur : internetd.togocel\\n✅ Mot de passe : laissez ce champ vide\\n📌 Redémarrez ensuite votre iPhone pour finaliser la configuration.\\n✨ Je reste à votre disposition pour toute assistance.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"apn configuration internet paramètres réglages données mobiles"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(46,46,1,'{"f":{"title":"Lettre d’engagement – client réticent à la rédiger","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n💛 Je comprends votre ressenti et vous remercie de votre compréhension. \\n🙏 Cependant, la lettre d’engagement est une mesure de sécurité essentielle pour protéger votre numéro.\\n📋 Les informations que vous y indiquez sont comparées à celles de notre base de données afin de confirmer votre identité et d''assurer un traitement fiable de votre demande.\\n🚀 Plus vite la procédure est complétée, plus vite votre demande de changement d’identité pourra être examinée.\\n🤝Une question ? Je vous accompagne vers la meilleure solution💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(47,47,1,'{"f":{"title":"Comptes Mixx Togo : montants plafonds et limites d’utilisation","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🚀 Besoin de plus de flexibilité ? \\nLe compte élargi peut vous permettre d''effectuer des opérations plus importantes en toute sérénité.\\nL’élargissement est gratuit en agence et sur l’application Mixx 😊\\nVoici les plafonds applicables selon votre type de compte :\\n🔹 Compte non élargi (ordinaire) \\n✅ Plafond mensuel : 200 000 FCFA \\n✅ Solde maximum : 200 000 FCFA\\n🔹 Compte élargi\\n✅ Plafond journalier : 2 000 000 FCFA \\n✅ Plafond hebdomadaire : 5 000 000 FCFA \\n✅ Plafond mensuel : 10 000 000 FCFA \\n✅ Solde maximum : 2 000 000 FCFA\\n📌 Ces plafonds concernent l''ensemble de vos opérations : dépôts, retraits, transferts et paiements.\\nJe reste disponible si vous avez d''autres questions. 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"plafond limite montant maximum solde"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(48,48,1,'{"f":{"title":"Relevé de transactions – procédure","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n👋 Accéder facilement et en toute sécurité à votre relevé de transactions!\\nIl vous suffit d''adresser votre demande à l''adresse électronique mixxbyyas@yas.tg en indiquant :\\n📱 Le numéro concerné\\n📅  La période souhaitée\\n🪪 Les photos recto et verso de votre pièce d''identité en cours de validité (Carte nationale d’identité, Passeport, Carte consulaire,  Carte de séjour,  Carte des forces armées togolaises, Permis de conduire) \\n🚀 Envoyez votre demande dès maintenant et bénéficiez d''un traitement rapide.\\n💛 Merci de votre confiance, je  suis là pour vous accompagner.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"relevé historique transactions détail"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(49,49,1,'{"f":{"title":"Annulation d’un transfert Mixx Togo","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🤝 Une erreur de transfert peut arriver à tout le monde!\\nPour toute annulation de votre transfert :\\n✅ Composez *145*8*4#\\n ✅ Renseignez votre code secret et la référence du transfert\\n ✅ Confirmez avec l''option 3\\n📌 Important :\\n⏰ L''annulation est possible dans un délai de 48 heures après le transfert.\\n🔄 Vous pouvez faire jusqu''à deux demandes d''annulation par jour.\\n💪 Plus vous agissez rapidement, plus vous augmentez vos chances  de restitution du montant.\\n💛 Je reste à vos côtés. Dites-moi si l''opération a abouti !","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"transfert envoi argent erreur mauvais numéro annuler"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(50,50,1,'{"f":{"title":"Désactiver le service Myzik","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nLe service Myzik est actuellement activé mais il peut être désactivé à tout moment.\\nSi vous ne souhaitez plus en bénéficier, vous pouvez le désactiver en composant : *909*5*5*00* 9*1#.\\n🤝N''hésitez pas à me faire part de vos retours, je vous accompagne au mieux.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"prélèvement débit abonnement désabonnement stop service payant"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(51,51,1,'{"f":{"title":"Demandes de sponsoring – contact dédié","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🤝 Merci de penser à Yas pour accompagner votre projet.\\nPour nous soumettre votre demande de sponsoring, il vous suffit d''écrire à 📩 sponsoring@yas.tg\\n✨ Cette adresse électronique vous garantit un interlocuteur adapté à votre projet. \\nExcellente journée {{prenom}} !","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"sponsoring partenariat événement"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(52,52,1,'{"f":{"title":"Demande d’emploi chez Yas Togo","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🌟 Merci pour l''intérêt que vous portez à Yas.\\n📩 Pour soumettre votre candidature, envoyez votre dossier à recrutement@yas.tg et pensez à joindre : \\n✅ Une lettre de motivation mettant en avant votre parcours et votre intérêt pour le poste\\n ✅ Un CV à jour\\n🚀 Osez franchir le pas et saisissez une opportunité de faire découvrir votre talent.\\nBonne chance pour la suite ! 🍀","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"emploi recrutement candidature cv stage travail"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(53,53,1,'{"f":{"title":"Demande hors périmètre – réponse négative","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋,\\nMerci pour votre message et votre confiance.\\nVotre demande ne concerne pas les services proposés par Yas et ne peut donc pas être traitée par nos équipes.\\n💡 Besoin d''aide sur nos offres, forfaits, internet, services mobiles ou Mixx ? \\nJe suis là pour vous guider vers la solution la plus adaptée.\\n Excellente journée {{prenom}} !","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(54,54,1,'{"f":{"title":"Reversement de solde Mixx– décès du titulaire du numéro ( cas du père)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n🕊️ Toutes nos pensées vous accompagnent dans cette épreuve.\\nPassez en agence avec les documents ci-dessous, nos équipes en agence sont disponibles pour vous assister dans vos démarches :\\n📷 Une pièce d''identité originale  de votre père ( du défunt)\\n 📄 Un acte ou document officiel attestant le décès de votre père.\\n 🤝 Un justificatif attestant que la personne qui demande le reversement est légalement mandatée ou habilitée à le faire: un certificat de non-opposition ni appel le désignant comme l’administrateur des biens\\n📷 Une pièce d’identité originale de l’administrateur des biens en cours de validité \\n🔐 Ces documents nous permettent de traiter la demande en toute sécurité et dans le respect des procédures en vigueur.\\nMerci pour votre confiance.💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"décès défunt héritage succession"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(55,55,1,'{"f":{"title":"Réinitialisation du code secret Mixx","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPour lancer la réinitialisation de votre code secret, merci de me transmettre :\\n📱 Le numéro concerné [Le Conseiller Clientèle s’assure, dès la prise en charge, que l’identité déclarée par le client correspond à celle renseignée dans le CRM.] 😊\\n📸 Les photos recto et verso de votre pièce d''identité valide\\n 💰 Le solde actuel de votre compte Mixx \\n🚀 Envoyez-les dès que vous êtes prêt(e), je m''occupe du reste. 💛\\nMerci pour votre confiance !","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"code secret pin puk oublié réinitialiser bloqué mot de passe"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(56,56,1,'{"f":{"title":"Renseignement sur les bonus en attente","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n✨ Bonne nouvelle !\\n Vos bonus sont bien pris en compte et vous seront attribués dès que possible.\\n💛  N''hésitez pas à me solliciter si vous avez besoin d''assistance.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"bonus récompense attente patienter instant un moment"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(57,57,1,'{"f":{"title":"Numéro bloqué en émission\\/réception – problème d’identification (MSA)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n🙏🏾 Merci pour votre message et pour votre confiance.\\nAprès vérification, votre numéro est actuellement suspendu en émission et en réception d''appels en raison d''une mise à jour requise de vos informations d''identification.\\n📍 Présentez-vous dans une agence Yas avec l''original de votre pièce d''identité en cours de validité afin de rétablir votre ligne.\\n💛 N’hésitez pas à me solliciter si vous avez besoin d''assistance.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"bloqué suspendu gelé débloquer"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(58,58,1,'{"f":{"title":"Difficulté d’activation du forfait voix – informations requises","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPour que je puisse analyser la situation et vous aider, merci de m''envoyer les éléments suivants :\\n1️⃣  Vos nom et prénom\\n2️⃣ Le numéro concerné\\n3️⃣ Une capture d''écran du message d''erreur affiché lors de l''activation du forfait voix\\n4️⃣ Le canal de souscription utilisé : Agence\\/PDV Express, Mixx, ou activation depuis un numéro autre que le vôtre\\n📌 Dès réception de ces informations, je fais les vérifications nécessaires et je reviens vers vous avec la solution la plus adaptée.\\n💛 Merci pour votre fidélité et à très vite ! 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(59,59,1,'{"f":{"title":"Compatibilité du terminal : SIM lock et double SIM","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n✨ Bonne nouvelle ! La majorité des téléphones que nous commercialisons sont compatibles avec tous les réseaux et ne présentent aucune restriction d''utilisation ✅\\n📱 Si votre appareil est concerné par une restriction et qu''il dispose de la fonctionnalité double SIM, voici la solution :\\n1️⃣  Insérer votre SIM Yas dans le port SIM 1\\n2️⃣ Insérer la SIM de l''autre opérateur dans le port SIM 2\\n🚀 Vous pourrez ainsi profiter pleinement des services des deux réseaux sur le même téléphone.\\n💛 N''hésitez pas à me solliciter si vous avez besoin d''assistance ou d''informations complémentaires.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"carte sim puce double dual ussd blocage"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(60,60,1,'{"f":{"title":"WhatsApp bloqué – orienter vers l’assistance WhatsApp","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n💛 Je comprends votre frustration face à la perte d''accès à votre compte WhatsApp.\\n📱 Pour les comptes WhatsApp bloqués, l''équipe d''assistance WhatsApp est la mieux placée pour intervenir et vous guider efficacement.\\n📱 Contactez-les directement pour bénéficier d''un accompagnement adapté à votre situation.\\n🤝 Dès que l''accès à votre compte sera rétabli, je serai ravi(e) de vous accompagner pour toute question relative aux services Yas.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"whatsapp bloqué suspendu gelé débloquer"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(61,61,1,'{"f":{"title":"Message reçu = service d’assistance (réponse générique)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nMerci pour l’intérêt que vous portez à Yas 🙏\\nLe message que vous avez reçu vient de notre service d’assistance, dédié à :\\n• Vos demandes de renseignements\\n• Vos requêtes spécifiques\\n• Vos réclamations liées à nos produits et services\\n📩 Écrivez-nous à tout moment : nos équipes sont  là pour vous accompagner 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(62,62,1,'{"f":{"title":"Invitation en privé pour assistance","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n💬 Besoin d''un accompagnement sur votre situation ? Écrivez-moi en message privé :\\n👉 Facebook Messenger https:\\/\\/m.me\\/yasintogo\\n 👉 WhatsApp +22890928888\\nJe reste disponible pour vous assister 💛😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"message privé messenger whatsapp inbox"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(63,63,1,'{"f":{"title":"Mobile Money – IMT non disponible dans le pays demandé (ex. Gabon)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n Merci pour votre intérêt 🙏\\n🚫 À ce jour, Mixx Togo ne dispose pas encore de partenaire Mobile Money au [pays : Gabon].\\n✨ Bonne nouvelle : notre réseau international continue de s''agrandir !\\n📩 Contactez-nous pour découvrir les destinations actuellement disponibles. 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(64,64,1,'{"f":{"title":"Communication de la marque et modèle du téléphone","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n📱 Pouvez-vous nous communiquer la marque et le modèle de votre téléphone ?\\n✅ Dès réception de ces informations, je prendrai en charge votre demande. 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(65,65,1,'{"f":{"title":"Guide rapide des syntaxes Yas Togo","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n📱 Pour vous simplifier la vie, voici les principales syntaxes Yas à conserver précieusement :\\n📌 L’essentiel\\n🔹 Connaître votre numéro : *555#\\n🔹 Consulter votre solde (forfaits en cours et crédit) : *909*0#\\n🌐 Souscrire à un forfait\\n📶 Forfaits internet : *909*2#\\n📞 Forfaits voix (appels) : *909*4# ou *909*3#\\n💸 Transfert ou prêt de crédit : *909*5#\\n🌍 Appels internationaux \\/ Roaming : *909*6#\\n🎁 Achat de forfait pour un tiers : *909*7#\\n🔐 Profil SOWE : *909*8#\\nℹ️ Infos sur votre numéro : *909*9#\\n💰 Mobile Money : composez *145# et explorez les options\\n🌐 Plus d’infos : yas.tg\\n📲 Pour une expérience encore plus fluide, vous pouvez aussi tout faire depuis Yas App, sans retenir de code 😉\\nJe reste disponible pour vous assister 💛😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"ussd code syntaxe composer"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(66,66,1,'{"f":{"title":"Prêt de crédit ou de forfait : comment en bénéficier ?","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n🔥 À court de crédit, de forfait internet ou voix ? \\n💳 Accédez  au service de prêt en composant *909*5*1#\\n ✅  Sélectionnez l''option de prêt qui vous intéresse\\n ✅  Si vous êtes éligible, le prêt est accordé après votre confirmation\\n💛 Je reste à vos côtés. Dites-moi si l''opération a abouti !","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"prêt crédit avance emprunt sos"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(67,67,1,'{"f":{"title":"Difficulté de réception d’appels","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJe comprends votre déception face à ce dysfonctionnement et je vous présente mes excuses pour la gêne occasionnée. 💛\\n🔎 Afin de nous aider à identifier précisément l''origine du problème, pourriez-vous nous communiquer le message exact que vos correspondants entendent lorsqu''ils tentent de vous joindre ?\\n🚀 Envoyez ce message dès maintenant pour une investigation et un traitement rapide.\\n💛 Merci de votre confiance, je suis là pour vous accompagner.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"appels réception entrants réseau"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(68,68,1,'{"f":{"title":"Difficulté de Réception d’appel – vérifier les paramètres réseau","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJe comprends votre déception face à ce dysfonctionnement et je vous présente mes excuses pour la gêne occasionnée. 💛\\n 📶 Vérifions ensemble les paramètres de votre accès au réseau .\\n✅ Allez dans  \\" Paramètres\\"  et sélectionnez  \\" Réseaux Mobiles\\" \\n✅ Sélectionnez  dans  \\" Type ou Mode réseau préféré\\" (en fonction de votre téléphone), votre préférence :  2G\\/3G,  3G\\/4G, LTE, 4G, 5G\\"  .\\n ✅ Redémarrez votre téléphone.\\n ✅ Effectuez un test de réception d''appel.\\n💛 Je reste à votre disposition pour vous accompagner.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(69,69,1,'{"f":{"title":"Consuter vos soldes et validités","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n✅ Consultez votre solde à tout moment en composant *909*0#\\n🌐 Pour vérifier la validité de votre abonnement Fibre Yas, composez *909*106#\\n💛 Je reste à votre disposition pour toute assistance complémentaire.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(70,70,1,'{"f":{"title":"SoWe – l’offre Yas dédiée aux jeunes","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nBonne nouvelle !\\nDécouvrez SoWe, une offre pensée pour les jeunes de 15 à 34 ans qui veulent profiter pleinement de chaque opportunité !\\n✅ Forfaits voix et internet à prix réduits\\n✅ Bonus de communication vers tous les réseaux\\n✅ Réductions chez nos partenaires\\n✅ Opportunités de stage, de formation et d’événements culturels\\n👉 Inscription gratuite : *909*81# \\n ✨Plus de détails sur www.yas.tg. \\n💛Je reste disponible si vous avez d''autres questions.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"jeu quiz concours gain cadeau récompense jeunes 15 34 ans sowe"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(71,71,1,'{"f":{"title":"Validité du forfait Fibre Yas","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n✅ Votre forfait sur le numéro {{numero}} reste actif jusqu’au {{date}}.\\n📲 Pour consulter la validité de votre abonnement Fibre Yas à tout moment, composez *909*106# et suivez les instructions.\\nMerci pour votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"fibre ftth internet domicile box modem wifi"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(72,72,1,'{"f":{"title":"Achat de validité indisponible – prorogation","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n🙏 L''offre Achat de validité n''est actuellement pas disponible.\\n💡 Mais voici une solution : vous pouvez prolonger votre utilisation en souscrivant à un forfait du même type et du même montant. Le volume sera cumulé et la validité sera automatiquement étendue selon la durée du nouveau forfait.\\n💛 Je reste à votre disposition pour vous accompagner.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(73,73,1,'{"f":{"title":"Difficulté d’envoi de SMS sur les téléphones 1+1 – configuration du centre de messagerie ( pour les autres téléphones la configuration est automatique)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJe comprends votre déception au vu de ce dysfonctionnement et je m''excuse pour la gêne occasionnée. \\n📶 Vérifions ensemble les paramètres du centre de messagerie de votre téléphone (1+1) : \\n 1️⃣ Allez dans \\" Messages\\" \\n 2️⃣ Appuyez sur les trois points en haut à droite.\\n 3️⃣ Sélectionnez Paramètres.\\n 4️⃣ Accédez à Plus de paramètres ou Paramètres SMS.\\n 5️⃣ Appuyez sur Centre de messages.\\n 6️⃣ S''assurez que le numéro affiché est bien +22890400009.\\n 7️⃣ Si nécessaire, corrigez-le puis enregistrez les modifications.\\n✅ Après ces étapes, essayez d''envoyer un SMS. \\n💛 Je reste à votre disposition pour vous accompagner.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"sms message"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(74,74,1,'{"f":{"title":"Déblocage Compte Mixx gelé - Création systématique d''un ticket qui sera traité par vos collègues de l''opération Mixx","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJe m’excuse pour la gêne occasionnée par l''absence d''accès à votre compte Mixx. \\nAprès vérification, votre compte est gelé, pourriez-vous me communiquer :\\n1️⃣ Vos nom(s) et prénom(s) ;\\n2️⃣ Le numéro concerné ;\\n3️⃣ Les circonstances du blocage du compte ;\\n✅ Envoyez -moi une photo recto verso de l''original de votre pièce d''identité en cours de validité.\\nNos équipes pourront déterminer si le déblocage peut être accordé.\\nMerci de votre compréhension.","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"bloqué suspendu gelé débloquer"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(75,75,1,'{"f":{"title":"Vérifier l’identité des agents de Distribution de SIM Marchand","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋 \\nMerci pour votre intérêt envers Yas. 💛\\n🙏  Nos équipes sont déjà sur le terrain pour accompagner les commerçants intéressés et leur proposer les SIM Marchand. \\nAvant de leur transmettre des informations confidentielles, demandez-leur leur nom complet, puis contactez-nous sur :\\n• 📱 WhatsApp : 90928888\\n• 📞 Appel : 1010 ou 888\\n✅ Nous avons l’identité de tous nos agents. Une fois leur identité confirmée, vous pouvez leur transmettre les informations nécessaires en toute sécurité. Ils reviendront quelques jours plus tard pour vous remettre votre SIM Marchand.\\nMerci pour votre confiance et votre vigilance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"carte sim puce marchand mpay point de vente pdv commerçant"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(76,76,1,'{"f":{"title":"Désabonnement du jeu Edu Quiz","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPour vous désabonner du jeu Edu Quiz, envoyez le mot STOP par SMS au 909 📲\\n💛 Merci de me tenir informé(e) du résultat. \\nJe reste à votre disposition pour toute assistance complémentaire. 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"jeu quiz concours gain cadeau récompense prélèvement débit abonnement désabonnement stop service payant"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(77,77,1,'{"f":{"title":"Épuisement rapide des données mobiles","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋 \\n🙏 Si votre forfait s''épuise rapidement, quelques réglages simples peuvent faire toute la différence.\\n📉 Causes fréquentes :\\n• Applications de streaming (vidéo, musique)\\n• Téléchargement de fichiers volumineux\\n• Consommation en arrière-plan par certaines applications\\n🔧 Astuce : limitez la consommation en arrière-plan\\n1️⃣ Ouvrez Paramètres\\n2️⃣ Allez dans Utilisation des données\\n3️⃣ Touchez les trois points en haut à droite\\n4️⃣ Sélectionnez Restreindre les données d’arrière-plan\\n👉 Les applications n’utiliseront plus vos données mobiles en arrière-plan (sauf en Wi-Fi).\\n💡 Vous pouvez aussi le faire application par application : touchez l’application dans la liste et activez « Restreindre les données d’arrière-plan ».\\nFaites-moi un retour après ces vérifications, je reste à votre disposition 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"data finit vite consommation internet forfait épuisé"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(78,78,1,'{"f":{"title":"SIM qui devrait fonctionner – test dans un autre téléphone","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋 \\nAprès vérification, votre numéro devrait fonctionner normalement.\\n📶 Et si nous essayions ensemble une petite manipulation pour tester votre sim?\\n👉 Insérez votre SIM dans un autre téléphone et faites un test d''appel.\\nSi le problème persiste, rendez-vous dans  l''une de nos agences YAS  avec:\\n✅  votre SIM\\n✅  l''original de votre pièce d’identité en cours de validité\\nVous serez pris(e) en charge rapidement. \\nMerci pour votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"carte sim puce"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(79,79,1,'{"f":{"title":"Plafond atteint – compte Mixx Standard","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n🙏 Après vérification, vous avez atteint le plafond mensuel de votre compte Mixx Standard, fixé à 200 000 F CFA.\\n🚀 Bonne nouvelle : l’élargissement de votre compte Mixx vous permet de réaliser des opérations avec des plafonds plus élevés.\\n✅ L’opération est gratuite, en agence Yas ou directement depuis l’application Mixx.\\nVoici les plafonds pour un compte élargi\\n✅ Plafond journalier : 2 000 000 FCFA \\n✅ Plafond hebdomadaire : 5 000 000 FCFA \\n✅ Plafond mensuel : 10 000 000 FCFA \\n✅ Solde maximum : 2 000 000 FCFA\\n📌 Ces plafonds concernent l''ensemble de vos opérations : dépôts, retraits, transferts et paiements.\\nJe reste disponible si vous avez d''autres questions. 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"plafond limite montant maximum solde"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(80,80,1,'{"f":{"title":"Élargissement de compte à distance (client à l’étranger)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nVous souhaitez élargir votre compte Mixx mais vous êtes actuellement à l''étranger ? 🌍\\n🚀  Bonne nouvelle : une solution existe !\\nConfiez simplement la démarche à une personne de confiance à l''aide d''une procuration légalisée ou notariée, qui vous représentera en agence.\\n👤 Cette personne devra se munir de l''original de :\\n✅ sa pièce d’identité en cours de validité\\n✅ votre pièce d’identité\\n✅La procuration officielle (notariée ou légalisée)doit  préciser :\\n1️⃣ L’objet de la demande\\n2️⃣ Le numéro à élargir\\n3️⃣ Les pièces d’identité des deux parties\\nJe reste à votre disposition  💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"kyc élargissement compte élargi pièces identité"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(81,81,1,'{"f":{"title":"Changement de langue de votre numéro","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nVous souhaitez changer la langue de communication de votre numéro ? 🌐 Rien de plus simple !\\n🚀 Suivez ces étapes :\\n1️⃣ Composez le 222 et lancez l''appel\\n2️⃣Tapez 3 et faites votre choix de langue\\nJe reste à vos cotés pour vous assister. 💛✨","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(82,82,1,'{"f":{"title":"Forfait spécifique (SPNET) – souscription sur invitation","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nCe forfait est un peu particulier 📦 : on y souscrit uniquement à la réception du message d’invitation.\\n📩 La syntaxe à utiliser est indiquée dans ce message : il vous suffit de la suivre dès que vous le recevez.\\nMerci pour votre fidélité 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(83,83,1,'{"f":{"title":"Informations requises pour une assistance personnalisée","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nAfin de vous apporter la meilleure assistance possible, j''ai besoin de quelques informations 📋✨🙏\\n🔹 Nom et prénom\\n🔹 Numéro concerné\\n🔹 Année d’achat du numéro\\n🔹 Date de la dernière recharge\\n🔹 Préciser si le numéro est utilisé uniquement sur WhatsApp ou s’il sert plus aux appels et aux SMS.\\n✅ Envoyez -moi une photo recto verso de l''original de votre pièce d''identité en cours de validité.\\n✅ Avec ces éléments, je vous apporte une réponse plus précise. \\nMerci pour votre confiance ! 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(84,84,1,'{"f":{"title":"Sécurité WhatsApp – compte possiblement piraté","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nMerci pour votre patience \\n🙏 Après vérification, les informations que vous avez transmises sont exactes.\\n📲 En général, la configuration d’un compte WhatsApp nécessite un code OTP envoyé sur la SIM liée au numéro.\\n⚠️ Si votre compte a été configuré sans que vous ayez accès à ce code, il est possible qu’il ait été piraté.\\n👉 Nous vous recommandons de contacter l’assistance WhatsApp pour demander la récupération de votre numéro. Elle est la mieux placée pour vous aider à le récupérer.\\nJe reste à votre écoute 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":"arnaque fraude escroquerie phishing piratage faux lien whatsapp"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(85,85,1,'{"f":{"title":"Offres promotionnelles – envoi automatique","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJe comprends votre impatience 😊 \\nCes offres ne sont pas envoyées manuellement : elles sont générées automatiquement par notre système selon des critères spécifiques.\\n⏳ Vous les recevrez dès qu’elles seront disponibles pour vous.\\n💡 En attendant, découvrez tous nos forfaits sur *909# ou sur Yas App 🚀\\nMerci pour votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(86,86,1,'{"f":{"title":"Souscrire à un forfait avec un prêt","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPas assez de crédit pour votre forfait ? Le prêt peut vous dépanner 💳\\n1️⃣ Composez la syntaxe du forfait souhaité\\n2️⃣ Au moment de choisir le mode de paiement, sélectionnez « crédit »\\n💡 Si vous êtes éligible, le prêt vous est proposé automatiquement.\\nBesoin d’assistance ? Je suis là 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"prêt crédit avance emprunt sos"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(87,87,1,'{"f":{"title":"Consultation du montant de prêt restant","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPour le moment, il n’existe pas de code pour consulter le montant du prêt restant à rembourser 🙏\\n📞 Pour obtenir cette information, contactez-nous directement : nous vous l’indiquerons avec plaisir.\\nMerci pour votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"prêt crédit avance emprunt sos"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(88,88,1,'{"f":{"title":"Numéro définitivement réattribué","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPour le moment, il n’existe pas de code pour consulter le montant du prêt restant à rembourser.\\n📞 Pour obtenir cette information, contactez-nous directement : nous vous l’indiquerons avec plaisir.\\nMerci pour votre confiance 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"numéro supprimé inactif réattribué récupérer reprise"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(89,89,1,'{"f":{"title":"Gestion des numéros inactifs – informations importantes","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🙏 Après vérification, je vous informe que ce numéro a été recréé puis revendu après une longue période d’inactivité, due à l’absence de recharges.\\n❌ Il est désormais attribué à un autre client et ne peut plus être récupéré.\\nJe comprends votre déception face à cette situation et vous présente mes sincères excuses pour le désagrément occasionné.\\nJe reste à votre disposition pour toute assistance. 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(90,90,1,'{"f":{"title":"Annulation d’achat de crédit Cash Power – CEET pour motif de : - double achat - absence de code cash power - erreur de montant lor de l''achat [Le conseiller prend les informations nécessaires pour tai","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPour traiter votre requête, envoyez -moi les informations suivantes :\\n✅ votre nom et prénom \\n✅ Le numéro qui a effectué la transaction\\n✅ Le numéro du compteur\\n✅ La date de l''achat de cash power\\n✅ Le montant réglé\\n✅ La référence de la transaction\\n✅ Autre contact\\n🔍 Après vérification, votre requête sera traitée et un retour vous sera communiqué.\\nMerci pour votre fidélité. 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":"cash power ceet électricité code"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(91,91,1,'{"f":{"title":"Assistance demandée par un non-titulaire du numéro (ex. fils\\/fille pour sa mère)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n🙏 Pour des raisons de sécurité, nous pouvons uniquement assister le titulaire du numéro.\\n😊 Pour vous assister, je vous propose deux solutions :\\n📞 Contactez le service client Mixx au 888 en présence de votre mère. Nos conseillers pourront échanger directement avec elle et effectuer les vérifications nécessaires en toute sécurité. 😊\\n📍Ou rendez-vous en agence Yas avec votre mère, munie de l’original de sa pièce d’identité en cours de validité.\\nMerci pour votre compréhension 🙏🏾","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(92,92,1,'{"f":{"title":"Repositionnement de solde Mixx","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nPour transférer le solde de votre compte vers un autre numéro, envoyez votre demande à mixxbyyas@yas.tg  en précisant :\\n✅ Le numéro source\\n✅ Le numéro destinataire\\n✅ Le solde à transférer\\n✅ Les photos recto\\/verso de l''original de votre pièce d’identité en cours de validité.\\n🔍 Après vérification, si votre dossier est conforme, le repositionnement sera effectué et un retour vous sera communiqué.\\nMerci pour votre fidélité. 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(93,93,1,'{"f":{"title":"Application Mixx – code de vérification (saisie manuelle désactivée)","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJe comprends votre situation.\\n🙏 Pour des raisons de sécurité, la saisie manuelle du code de vérification est désactivée.\\n📲 Pour finaliser la configuration :\\n✅ Insérez la carte SIM dans le téléphone concerné. \\n✅ Le code de vérification est alors détecté et validé automatiquement dès sa réception.\\nDites-moi si tout a bien fonctionné. 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(94,94,1,'{"f":{"title":"KIT Yas Ordinaire – disponibilité et tarif","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\n📱 Le KIT Yas Ordinaire est disponible à 500 FCFA en agence Yas, point de contact ou auprès de nos agents commerciaux.\\n🎁 À l''activation, profitez de : \\n✅ 1 000 FCFA de crédit d''appel\\n✅ 20 SMS\\n✅ 200 Mo de data\\n✅ 200 FCFA sur votre compte Mixx, utilisables pour souscrire à un forfait.\\n🚀 Procurez-vous votre KIT dès aujourd’hui !\\n💛 Une question ? Je suis là pour vous assister. 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(95,95,1,'{"f":{"title":"Vérification d’identité – accès aux informations du numéro","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJe comprends que ces vérifications puissent sembler contraignantes \\n🙏 Elles servent à protéger vos données : nous devons nous assurer que la personne qui demande les informations est bien l’utilisateur légitime du numéro.\\n🔐 Sans ces éléments, nous ne pourrons pas communiquer d’informations sur ce numéro, pour des raisons de sécurité et de confidentialité.\\n👉 Faites-moi un retour après ces étapes, je reste disponible 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"AUT","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(96,96,1,'{"f":{"title":"Consultation des frais de Mixx Togo","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\nBesoin de connaître les frais de retrait ou de transaction ? 😊\\n📱 Composez *145*8*6# et suivez les instructions à l’écran.\\n✅ Vous obtiendrez instantanément le tarif correspondant au montant souhaité.\\nJe reste disponible pour d''autres questions 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MIX","keywords":null},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(97,97,1,'{"f":{"title":"Création du code secret SOS Crédit","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n✅ Pour activer votre code secret SOS Crédit, composez *909*5*1*5# 🔐\\n⚠️ Gardez-le précieusement : ce code est unique et ne pourra pas être modifié ou récupéré en cas d''oubli.\\nJe reste disponible si vous avez besoin d''assistance 💛😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"code secret pin puk oublié réinitialiser bloqué mot de passe prêt crédit avance emprunt sos"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(98,98,1,'{"f":{"title":"Modification du débit – fibre optique","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}} 👋\\n🚀 Besoin d’augmenter ou de réduire le débit de votre fibre ? C’est simple, rapide et totalement gratuit :\\n✅ Composez *909*10*1*2# et suivez les instructions à l’écran.\\n✅ Modification prise en compte rapidement.\\n✅ Aucun frais à prévoir\\n💛 N’hésitez pas à me confirmer si votre demande a abouti. Je reste disponible. 😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"fibre ftth internet domicile box modem wifi lenteur connexion lente débit coupure"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(99,99,1,'{"f":{"title":"Pas de connexion – Fibre","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nExcusez- nous pour ce désagrément \\n🙏. Pour une prise en charge rapide, merci de m''envoyer :\\n✅ Un numéro de téléphone de contact\\n✅ Le numéro de votre ligne fibre\\n✅ Votre quartier de résidence\\n✅ Une courte vidéo 🎥 du routeur montrant les voyants allumés\\n🔎 Ces éléments nous aideront à identifier rapidement le problème et à accélérer son traitement.\\nMerci pour votre collaboration 💛😊","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"FIB","keywords":"fibre ftth internet domicile box modem wifi lenteur connexion lente débit coupure"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21'),
(100,100,1,'{"f":{"title":"Prélèvements liés à Éduquiz – désabonnement","kind":null,"channel_id":null,"language":"fr","situation":null,"body":"Bonjour {{prenom}}👋\\nJ’ai trouvé l’origine des prélèvements 🔎 Ils sont liés à votre souscription au jeu Éduquiz.\\n📩 Pour vous désabonner, envoyez STOP par SMS au 909.\\nN''hésitez pas à me confirmer si l''opération a abouti 💛","avoid":null,"required_phrases":null,"team_id":null,"mandatory":0,"owner_id":null,"family":"MOB","keywords":"relevé historique transactions détail jeu quiz concours gain cadeau récompense prélèvement débit abonnement désabonnement stop service payant"},"points":[]}',NULL,'','Import de la bibliothèque','2026-11-15 17:50:21');
