-- CXO Excellence Hub — script MySQL 8 (schéma + données de démonstration)
-- Administrateur : admin@cxo.local / ChangeMe-2026x (changement imposé à la première connexion)
-- Comptes démo : rh@, manager@, securite@, audit@ demo.cxo / Demo-Yas2026
-- + organisation RÉELLE (41 stores, ~490 personnes avec compte de connexion, mot de passe provisoire Yas-Togo-2026) + jeu de test volumineux d'activité (données fictives) :  6 mois d'évaluations qualité, coachings, absences, ~750 tickets. Comptes supplémentaires : qualite1..5@, tech2..6@, cc1..90@ demo.cxo / Demo-Yas2026
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
CREATE DATABASE IF NOT EXISTS cxo_hub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cxo_hub;

DROP TABLE IF EXISTS dash_config;
CREATE TABLE IF NOT EXISTS dash_config (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  role_id INT,
  user_id INT,
  widget VARCHAR(40) NOT NULL,
  visible TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_dash_config_role_id ON dash_config(role_id);
CREATE INDEX idx_dash_config_user_id ON dash_config(user_id);

DROP TABLE IF EXISTS roles;
CREATE TABLE IF NOT EXISTS roles (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(60) NOT NULL UNIQUE,
  name VARCHAR(120) NOT NULL,
  description VARCHAR(255),
  is_system TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS permissions;
CREATE TABLE IF NOT EXISTS permissions (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(80) NOT NULL UNIQUE,
  label VARCHAR(190) NOT NULL,
  module VARCHAR(60)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS role_permissions;
CREATE TABLE IF NOT EXISTS role_permissions (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  role_id BIGINT UNSIGNED NOT NULL,
  permission_id BIGINT UNSIGNED NOT NULL,
  FOREIGN KEY (role_id) REFERENCES roles(id),
  FOREIGN KEY (permission_id) REFERENCES permissions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_role_permissions_role_id ON role_permissions(role_id);
CREATE INDEX idx_role_permissions_permission_id ON role_permissions(permission_id);

DROP TABLE IF EXISTS users;
CREATE TABLE IF NOT EXISTS users (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(190) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'active',
  failed_attempts INT DEFAULT '0',
  locked_until DATETIME,
  last_login_at DATETIME,
  last_ip VARCHAR(45),
  must_change_password TINYINT(1) NOT NULL DEFAULT 0,
  employer_code VARCHAR(60),
  employee_id INT,
  blocked_reason VARCHAR(255),
  blocked_at DATETIME,
  blocked_by INT,
  created_at DATETIME,
  updated_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_users_employee_id ON users(employee_id);

DROP TABLE IF EXISTS user_roles;
CREATE TABLE IF NOT EXISTS user_roles (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT UNSIGNED NOT NULL,
  role_id BIGINT UNSIGNED NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (role_id) REFERENCES roles(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_user_roles_user_id ON user_roles(user_id);
CREATE INDEX idx_user_roles_role_id ON user_roles(role_id);

DROP TABLE IF EXISTS pw_tokens;
CREATE TABLE IF NOT EXISTS pw_tokens (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT UNSIGNED NOT NULL,
  token_hash VARCHAR(64) NOT NULL UNIQUE,
  purpose VARCHAR(12) NOT NULL DEFAULT 'reset',
  expires_at DATETIME NOT NULL,
  used_at DATETIME,
  created_by INT,
  created_at DATETIME,
  FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_pw_tokens_user_id ON pw_tokens(user_id);

DROP TABLE IF EXISTS pw_requests;
CREATE TABLE IF NOT EXISTS pw_requests (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id INT,
  email VARCHAR(190) NOT NULL,
  reason VARCHAR(300),
  status VARCHAR(12) NOT NULL DEFAULT 'open',
  ip VARCHAR(45),
  created_at DATETIME,
  handled_by INT,
  handled_at DATETIME,
  note VARCHAR(300)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_pw_requests_user_id ON pw_requests(user_id);
CREATE INDEX idx_pw_requests_status ON pw_requests(status);
CREATE INDEX idx_pw_requests_created_at ON pw_requests(created_at);

DROP TABLE IF EXISTS login_attempts;
CREATE TABLE IF NOT EXISTS login_attempts (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(190),
  ip VARCHAR(45),
  success TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_login_attempts_email ON login_attempts(email);
CREATE INDEX idx_login_attempts_created_at ON login_attempts(created_at);

DROP TABLE IF EXISTS audit_logs;
CREATE TABLE IF NOT EXISTS audit_logs (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  created_at DATETIME NOT NULL,
  user_id INT,
  user_name VARCHAR(150),
  action VARCHAR(60) NOT NULL,
  entity_type VARCHAR(60),
  entity_id VARCHAR(60),
  before_json TEXT,
  after_json TEXT,
  ip VARCHAR(45)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_audit_logs_created_at ON audit_logs(created_at);
CREATE INDEX idx_audit_logs_user_id ON audit_logs(user_id);
CREATE INDEX idx_audit_logs_action ON audit_logs(action);
CREATE INDEX idx_audit_logs_entity_type ON audit_logs(entity_type);

DROP TABLE IF EXISTS user_activity_events;
CREATE TABLE IF NOT EXISTS user_activity_events (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  created_at DATETIME NOT NULL,
  user_id INT,
  user_name VARCHAR(150),
  role_code VARCHAR(60),
  team_name VARCHAR(120),
  session_hash VARCHAR(64),
  event_type VARCHAR(40) NOT NULL,
  module VARCHAR(60),
  menu_code VARCHAR(60),
  route VARCHAR(190),
  url VARCHAR(500),
  method VARCHAR(10),
  object_type VARCHAR(60),
  object_id VARCHAR(60),
  status_code INT,
  result VARCHAR(20),
  duration_ms INT,
  ip VARCHAR(45),
  country VARCHAR(80),
  city VARCHAR(120),
  network VARCHAR(20),
  device VARCHAR(30),
  os VARCHAR(40),
  browser VARCHAR(40),
  referer VARCHAR(300)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_user_activity_events_created_at ON user_activity_events(created_at);
CREATE INDEX idx_user_activity_events_user_id ON user_activity_events(user_id);
CREATE INDEX idx_user_activity_events_session_hash ON user_activity_events(session_hash);
CREATE INDEX idx_user_activity_events_event_type ON user_activity_events(event_type);
CREATE INDEX idx_user_activity_events_module ON user_activity_events(module);
CREATE INDEX idx_user_activity_events_result ON user_activity_events(result);
CREATE INDEX idx_user_activity_events_ip ON user_activity_events(ip);
CREATE INDEX idx_user_activity_events_city ON user_activity_events(city);

DROP TABLE IF EXISTS user_activity_summaries;
CREATE TABLE IF NOT EXISTS user_activity_summaries (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  day DATE NOT NULL,
  module VARCHAR(60),
  event_type VARCHAR(40),
  events INT,
  users INT,
  errors INT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_user_activity_summaries_day ON user_activity_summaries(day);

DROP TABLE IF EXISTS geo_ranges;
CREATE TABLE IF NOT EXISTS geo_ranges (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  ip_from DECIMAL(12,2) NOT NULL,
  ip_to DECIMAL(12,2) NOT NULL,
  country VARCHAR(80),
  city VARCHAR(120)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_geo_ranges_ip_from ON geo_ranges(ip_from);

DROP TABLE IF EXISTS settings;
CREATE TABLE IF NOT EXISTS settings (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  k VARCHAR(120) NOT NULL UNIQUE,
  v TEXT,
  updated_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS ref_lists;
CREATE TABLE IF NOT EXISTS ref_lists (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(80) NOT NULL UNIQUE,
  label VARCHAR(150) NOT NULL,
  module VARCHAR(60),
  active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS ref_values;
CREATE TABLE IF NOT EXISTS ref_values (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  list_id BIGINT UNSIGNED NOT NULL,
  code VARCHAR(80) NOT NULL,
  label VARCHAR(190) NOT NULL,
  sort_order INT DEFAULT '0',
  color VARCHAR(20),
  active TINYINT(1) NOT NULL DEFAULT 1,
  FOREIGN KEY (list_id) REFERENCES ref_lists(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ref_values_list_id ON ref_values(list_id);

DROP TABLE IF EXISTS menu_items;
CREATE TABLE IF NOT EXISTS menu_items (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  parent_id INT,
  code VARCHAR(60) NOT NULL UNIQUE,
  label VARCHAR(120) NOT NULL,
  icon VARCHAR(40),
  url VARCHAR(190),
  permission VARCHAR(80),
  sort_order INT DEFAULT '0',
  active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_menu_items_parent_id ON menu_items(parent_id);

DROP TABLE IF EXISTS channels;
CREATE TABLE IF NOT EXISTS channels (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(40) NOT NULL UNIQUE,
  name VARCHAR(120) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  lead_employee_id INT,
  kind VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS stores;
CREATE TABLE IF NOT EXISTS stores (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(40) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  city VARCHAR(120),
  region VARCHAR(120),
  active TINYINT(1) NOT NULL DEFAULT 1,
  org_unit_id INT,
  lead_employee_id INT,
  zone_id INT,
  locality VARCHAR(120),
  email VARCHAR(190),
  phone VARCHAR(40),
  phone2 VARCHAR(40),
  address VARCHAR(255),
  situation VARCHAR(300),
  gps_lat VARCHAR(20),
  gps_lng VARCHAR(20),
  hours VARCHAR(200)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_stores_org_unit_id ON stores(org_unit_id);
CREATE INDEX idx_stores_zone_id ON stores(zone_id);

DROP TABLE IF EXISTS positions;
CREATE TABLE IF NOT EXISTS positions (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(40) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  org_level INT,
  grade_id INT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_positions_grade_id ON positions(grade_id);

DROP TABLE IF EXISTS ep_plans;
CREATE TABLE IF NOT EXISTS ep_plans (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  period_label VARCHAR(60) NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'open',
  note TEXT,
  remind1_days INT DEFAULT '10',
  remind2_days INT DEFAULT '3',
  remind_email TINYINT(1) NOT NULL DEFAULT 1,
  created_by INT,
  created_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ep_plans_status ON ep_plans(status);

DROP TABLE IF EXISTS ep_programmes;
CREATE TABLE IF NOT EXISTS ep_programmes (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  plan_id BIGINT UNSIGNED NOT NULL,
  activity VARCHAR(150) NOT NULL,
  org_unit_id INT,
  name VARCHAR(200) NOT NULL,
  owner_employee_id INT,
  owner_label VARCHAR(150),
  timeline VARCHAR(100),
  status VARCHAR(12) NOT NULL DEFAULT 'not_started',
  progress INT DEFAULT '0',
  comment TEXT,
  sort_order INT DEFAULT '0',
  created_by INT,
  updated_by INT,
  updated_at DATETIME,
  reminded_at DATETIME,
  reminded1_at DATETIME,
  reminded2_at DATETIME,
  created_at DATETIME,
  FOREIGN KEY (plan_id) REFERENCES ep_plans(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ep_programmes_plan_id ON ep_programmes(plan_id);
CREATE INDEX idx_ep_programmes_activity ON ep_programmes(activity);
CREATE INDEX idx_ep_programmes_owner_employee_id ON ep_programmes(owner_employee_id);

DROP TABLE IF EXISTS ep_initiatives;
CREATE TABLE IF NOT EXISTS ep_initiatives (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  programme_id BIGINT UNSIGNED NOT NULL,
  label VARCHAR(300) NOT NULL,
  timeline VARCHAR(60),
  status VARCHAR(12) NOT NULL DEFAULT 'not_started',
  progress INT DEFAULT '0',
  comment TEXT,
  owner_employee_id INT,
  activity VARCHAR(150),
  updated_at DATETIME,
  reminded1_at DATETIME,
  reminded2_at DATETIME,
  sort_order INT DEFAULT '0',
  FOREIGN KEY (programme_id) REFERENCES ep_programmes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ep_initiatives_programme_id ON ep_initiatives(programme_id);
CREATE INDEX idx_ep_initiatives_owner_employee_id ON ep_initiatives(owner_employee_id);

DROP TABLE IF EXISTS ep_subs;
CREATE TABLE IF NOT EXISTS ep_subs (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  initiative_id BIGINT UNSIGNED NOT NULL,
  label VARCHAR(300) NOT NULL,
  timeline VARCHAR(60),
  status VARCHAR(12) NOT NULL DEFAULT 'not_started',
  progress INT DEFAULT '0',
  comment TEXT,
  sort_order INT DEFAULT '0',
  updated_at DATETIME,
  FOREIGN KEY (initiative_id) REFERENCES ep_initiatives(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ep_subs_initiative_id ON ep_subs(initiative_id);

DROP TABLE IF EXISTS msg_messages;
CREATE TABLE IF NOT EXISTS msg_messages (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  thread_id INT,
  parent_id INT,
  sender_id BIGINT UNSIGNED NOT NULL,
  subject VARCHAR(190) NOT NULL,
  body TEXT NOT NULL,
  scope VARCHAR(12) DEFAULT 'direct',
  sender_deleted TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL,
  FOREIGN KEY (sender_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_msg_messages_thread_id ON msg_messages(thread_id);
CREATE INDEX idx_msg_messages_sender_id ON msg_messages(sender_id);
CREATE INDEX idx_msg_messages_created_at ON msg_messages(created_at);

DROP TABLE IF EXISTS msg_recipients;
CREATE TABLE IF NOT EXISTS msg_recipients (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  message_id BIGINT UNSIGNED NOT NULL,
  user_id BIGINT UNSIGNED NOT NULL,
  read_at DATETIME,
  starred TINYINT(1) NOT NULL DEFAULT 0,
  deleted TINYINT(1) NOT NULL DEFAULT 0,
  FOREIGN KEY (message_id) REFERENCES msg_messages(id),
  FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_msg_recipients_message_id ON msg_recipients(message_id);
CREATE INDEX idx_msg_recipients_user_id ON msg_recipients(user_id);

DROP TABLE IF EXISTS msg_files;
CREATE TABLE IF NOT EXISTS msg_files (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  message_id BIGINT UNSIGNED NOT NULL,
  original_name VARCHAR(190) NOT NULL,
  stored_name VARCHAR(80) NOT NULL UNIQUE,
  mime VARCHAR(100),
  size INT,
  created_at DATETIME,
  FOREIGN KEY (message_id) REFERENCES msg_messages(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_msg_files_message_id ON msg_files(message_id);

DROP TABLE IF EXISTS fo_categories;
CREATE TABLE IF NOT EXISTS fo_categories (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(120) NOT NULL UNIQUE,
  description VARCHAR(300),
  sort_order INT DEFAULT '0',
  staff_only TINYINT(1) NOT NULL DEFAULT 0,
  active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS fo_topics;
CREATE TABLE IF NOT EXISTS fo_topics (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  category_id BIGINT UNSIGNED NOT NULL,
  user_id INT NOT NULL,
  title VARCHAR(190) NOT NULL,
  pinned TINYINT(1) NOT NULL DEFAULT 0,
  locked TINYINT(1) NOT NULL DEFAULT 0,
  replies INT DEFAULT '0',
  views INT DEFAULT '0',
  created_at DATETIME NOT NULL,
  last_post_at DATETIME NOT NULL,
  FOREIGN KEY (category_id) REFERENCES fo_categories(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_fo_topics_category_id ON fo_topics(category_id);
CREATE INDEX idx_fo_topics_user_id ON fo_topics(user_id);
CREATE INDEX idx_fo_topics_last_post_at ON fo_topics(last_post_at);

DROP TABLE IF EXISTS fo_posts;
CREATE TABLE IF NOT EXISTS fo_posts (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  topic_id BIGINT UNSIGNED NOT NULL,
  user_id INT NOT NULL,
  body TEXT NOT NULL,
  created_at DATETIME NOT NULL,
  edited_at DATETIME,
  FOREIGN KEY (topic_id) REFERENCES fo_topics(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_fo_posts_topic_id ON fo_posts(topic_id);
CREATE INDEX idx_fo_posts_user_id ON fo_posts(user_id);

DROP TABLE IF EXISTS ag_batches;
CREATE TABLE IF NOT EXISTS ag_batches (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  label VARCHAR(190) NOT NULL,
  scope VARCHAR(20) NOT NULL,
  scope_ref VARCHAR(150),
  created_by INT,
  created_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS ag_campaigns;
CREATE TABLE IF NOT EXISTS ag_campaigns (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(190) NOT NULL,
  period_type VARCHAR(10) NOT NULL,
  period_start DATE NOT NULL,
  period_end DATE NOT NULL,
  opens_on DATE NOT NULL,
  closes_on DATE NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'planned',
  remind1_days INT DEFAULT '7',
  remind2_days INT DEFAULT '3',
  remind_email TINYINT(1) NOT NULL DEFAULT 1,
  reminded1_at DATETIME,
  reminded2_at DATETIME,
  created_by INT,
  created_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ag_campaigns_status ON ag_campaigns(status);

DROP TABLE IF EXISTS ep_updates;
CREATE TABLE IF NOT EXISTS ep_updates (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  programme_id BIGINT UNSIGNED NOT NULL,
  period VARCHAR(60),
  status VARCHAR(12),
  progress INT,
  comment TEXT,
  detail TEXT,
  user_id INT,
  created_at DATETIME,
  FOREIGN KEY (programme_id) REFERENCES ep_programmes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_ep_updates_programme_id ON ep_updates(programme_id);

DROP TABLE IF EXISTS zones;
CREATE TABLE IF NOT EXISTS zones (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(40) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  lead_employee_id INT,
  active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS grades;
CREATE TABLE IF NOT EXISTS grades (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(40) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  rank_no INT DEFAULT '99',
  active TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS employers;
CREATE TABLE IF NOT EXISTS employers (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(60) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  kind VARCHAR(10) NOT NULL DEFAULT 'interim',
  contact VARCHAR(190),
  active TINYINT(1) NOT NULL DEFAULT 1,
  prefix VARCHAR(10),
  logo VARCHAR(60),
  slogan VARCHAR(190),
  sector VARCHAR(150),
  legal_form VARCHAR(80),
  capital VARCHAR(60),
  rccm VARCHAR(60),
  nif VARCHAR(60),
  cnss VARCHAR(60),
  address VARCHAR(300),
  phone VARCHAR(60),
  email VARCHAR(190),
  head_title VARCHAR(100),
  head_name VARCHAR(150),
  head_email VARCHAR(190),
  hr_title VARCHAR(100),
  hr_name VARCHAR(150),
  hr_email VARCHAR(190),
  doc_header VARCHAR(600),
  doc_footer VARCHAR(600),
  header_img VARCHAR(60),
  footer_img VARCHAR(60)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS teams;
CREATE TABLE IF NOT EXISTS teams (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(40) NOT NULL UNIQUE,
  name VARCHAR(150) NOT NULL,
  channel_id BIGINT UNSIGNED,
  active TINYINT(1) NOT NULL DEFAULT 1,
  org_unit_id INT,
  lead_employee_id INT,
  office VARCHAR(10),
  FOREIGN KEY (channel_id) REFERENCES channels(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_teams_channel_id ON teams(channel_id);
CREATE INDEX idx_teams_org_unit_id ON teams(org_unit_id);

DROP TABLE IF EXISTS employees;
CREATE TABLE IF NOT EXISTS employees (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  matricule_confirmed TINYINT(1) NOT NULL DEFAULT 1,
  matricule VARCHAR(40) NOT NULL UNIQUE,
  first_name VARCHAR(100) NOT NULL,
  last_name VARCHAR(100) NOT NULL,
  email VARCHAR(190),
  phone VARCHAR(40),
  team_id BIGINT UNSIGNED,
  store_id BIGINT UNSIGNED,
  channel_id BIGINT UNSIGNED,
  position_id BIGINT UNSIGNED,
  manager_id INT,
  hire_date DATE,
  contract_type VARCHAR(60),
  status VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at DATETIME,
  updated_at DATETIME,
  org_unit_id INT,
  org_level INT,
  photo VARCHAR(60),
  employer VARCHAR(120),
  placement VARCHAR(6),
  host_company VARCHAR(150),
  job_function VARCHAR(120),
  qa_ref_type VARCHAR(40),
  qa_ref VARCHAR(80),
