DROP TABLE IF EXISTS sv_sources;
CREATE TABLE IF NOT EXISTS sv_sources (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  folder VARCHAR(60) NOT NULL UNIQUE,
  mapping_id INT NOT NULL,
  survey_id INT,
  frequency VARCHAR(8) NOT NULL DEFAULT 'daily',
  active TINYINT(1) NOT NULL DEFAULT 1,
  last_run DATETIME,
  last_result VARCHAR(300),
  created_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS qn_profiles;
CREATE TABLE IF NOT EXISTS qn_profiles (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(40) NOT NULL,
  name VARCHAR(150) NOT NULL,
  version INT NOT NULL DEFAULT '1',
  effective_from DATE NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  priority INT DEFAULT '10',
  channel_kind VARCHAR(20),
  function_like VARCHAR(120),
  position_id INT,
  team_id INT,
  w_qc DECIMAL(12,2) DEFAULT '100',
  w_self DECIMAL(12,2) DEFAULT '0',
  w_store DECIMAL(12,2) DEFAULT '0',
  w_team DECIMAL(12,2) DEFAULT '0',
  csat_mode VARCHAR(6) DEFAULT 'pct',
  agg_mode VARCHAR(6) DEFAULT 'all',
  min_qc INT DEFAULT '1',
  min_csat INT,
  missing VARCHAR(12) DEFAULT 'redistribute',
  note VARCHAR(500),
  created_by INT,
  created_at DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_qn_profiles_code ON qn_profiles(code);
CREATE INDEX idx_qn_profiles_effective_from ON qn_profiles(effective_from);

DROP TABLE IF EXISTS store_slots;
