  FOREIGN KEY (slot_id) REFERENCES store_slots(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_store_hours_store_id ON store_hours(store_id);
CREATE INDEX idx_store_hours_slot_id ON store_hours(slot_id);

DROP TABLE IF EXISTS sv_providers;
CREATE TABLE IF NOT EXISTS sv_providers (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
